y_id=rf.facility_id WHERE rl.district_normalized=?5)) AND (?6='' OR f.facility_id IN(SELECT COALESCE(om.master_facility_id,fo.facility_id) FROM facility_organization fo JOIN organization o USING(organization_id) LEFT JOIN logical_facility_member om ON om.member_facility_id=fo.facility_id WHERE o.organization_name LIKE '%'||?6||'%')) AND (?7='' OR f.facility_id IN(SELECT COALESCE(sm.master_facility_id,sf.facility_id) FROM facility sf LEFT JOIN logical_facility_member sm ON sm.member_facility_id=sf.facility_id WHERE sf.facility_status=?7))